def replace_class(text, old, new):
    pat=re.compile(r'<svg\b[^>]*class="[^"]*\blucide-'+re.escape(old)+r'\b[^"]*"[^>]*>.*?</svg>', re.S)
    return pat.sub(new, text)


global_map={
    'x':'x','arrow-left':'chevron-left','arrow-right':'chevron-right','rotate-ccw':'rotate-cw',
    'house':'house','star':'star','history':'rotate-ccw-clock','download':'download','settings':'settings',
    'search':'search','mic':'mic','puzzle':'puzzle','panel-left':'panel-left','more-horizontal':'ellipsis',
    'plus':'plus','minus':'minus','square':'square'
}

for p in root.rglob('*'):
    if p.suffix not in {'.html','.js'} or p.name=='lucide.js':
        continue
    text=p.read_text(encoding='utf-8')
    for old,new in global_map.items():
        text=replace_class(text,old,svgs[new])
    p.write_text(text,encoding='utf-8')


p=root/'settings.html'
text=p.read_text(encoding='utf-8')
context={
    'appearance':'palette','typography':'case-sensitive','browsing':'search','privacy':'shield-lock','language':'languages','trust':'monitor-cog','about':'info'
}
for panel,icon in context.items():
    pat=re.compile(r'(<button class="nav-item"[^>]*data-panel="'+re.escape(panel)+r'"[^>]*>).*?(</button>)',re.S)
    def repl(m, icon=icon):
        block=m.group(0)
        block=re.sub(r'<svg\b[^>]*>.*?</svg>\s*', svgs[icon]+'\n        ', block, count=1, flags=re.S)
        return block
    text=pat.sub(repl,text)
p.write_text(text,encoding='utf-8')



from html import unescape

def svg_to_data(svg):
    inner=re.search(r'<svg[^>]*>(.*?)</svg>',svg,re.S).group(1)
    out=[]
    for m in re.finditer(r'<(path|circle|rect|polygon)\s+([^>]*?)(?:/|)>',inner):
        tag=m.group(1); attrs={}
        for k,v in re.findall(r'([\w:-]+)="([^"]*)"',m.group(2)):
            attrs[k]=v
        out.append([tag,attrs])
    return out

lp=root/'lucide.js'
lt=lp.read_text(encoding='utf-8')

for name,svg in svgs.items():
    data=svg_to_data(svg)
    
    entry=json.dumps(data,separators=(',',':'))
    
    pattern=re.compile(r"    '"+re.escape(name)+r"': \[.*?\],\n",re.S)
    replacement="    '"+name+"': "+entry+",\n"
    if pattern.search(lt):
        lt=pattern.sub(replacement,lt,count=1)
    else:
        marker='  };\n\n  function createIcon'
        lt=lt.replace(marker, replacement+'  };\n\n  function createIcon',1)

lt=lt.replace("el.classList.add('lucide', `lucide-${name}`);", "el.classList.add('lucide', `lucide-${name}-icon`, `lucide-${name}`);")
lt=lt.replace("class=\"lucide lucide-${name}\"", "class=\"lucide lucide-${name}-icon lucide-${name}\"")
lp.write_text(lt,encoding='utf-8')

print('done')
